<script setup lang="ts">import {usePropertyStore} from '@/hooks/property';import {woodPhotoDefaults} from '@/wood-photo-clock';const property=usePropertyStore();</script><template><section><h3>高清木纹翻页时钟</h3><p>高清材质底图 · 月日时分秒独立翻页</p><label>翻页动画<input type="checkbox" :checked="property.settings.animate!==false" @change="property.settings.animate=($event.target as HTMLInputElement).checked"></label><label>动画速度<select :value="property.settings.duration||440" @change="property.settings.duration=Number(($event.target as HTMLSelectElement).value)"><option :value="260">快速</option><option :value="440">标准</option><option :value="760">舒缓</option></select></label><label>12 小时制<input type="checkbox" :checked="property.settings.hour12===true" @change="property.settings.hour12=($event.target as HTMLInputElement).checked"></label><label>图像传输<select :value="property.settings.transport||'compatible'" @change="property.settings.transport=($event.target as HTMLSelectElement).value"><option value="compatible">兼容模式</option><option value="binary">二进制 PNG（实验）</option></select></label><button @click="Object.assign(property.settings,woodPhotoDefaults)">恢复默认</button></section></template><style scoped>section{padding:16px;color:#eee;font:13px 'Microsoft YaHei',sans-serif}label{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:16px 0}p{opacity:.65;line-height:1.7}button,select{padding:7px;background:#392b20;color:#fff;border:1px solid #8d7357;border-radius:5px}button{cursor:pointer}</style>
